package cli

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The promise at the top of both READMEs said "nothing created anywhere", with
// no condition, under a "Generated by ... Do not edit by hand" marker. Only the
// counts in that block came from an artefact; this sentence was a Go literal,
// which is the defect docs/conformance.md names as "Generated is not derived".
//
// And docs/limits.md measures the opposite, in the section this test reads: an
// apply that "created its instance IP on this emulator and died on
// `Put \"https://<bucket>.s3.fr-par.scw.cloud/\"` — one run, half local, half
// not", plus three more paths.
//
// So the rule this test holds is not "say the right sentence", which would be
// prose guarding prose. It is: **while the limits page carries a measured
// escape path, the promise has to point at it.** Delete the pointer and this
// test fails; delete the section from limits.md and it stops asking, because
// then there is nothing to bound.
func TestThePromiseNamesTheLimitThatBoundsIt(t *testing.T) {
	root := repoRoot(t)

	limits, err := os.ReadFile(filepath.Join(root, "docs", "limits.md"))
	if err != nil {
		t.Fatalf("read the limits page: %v", err)
	}
	const escape = "## A run presented as local can still reach the real cloud"
	if !strings.Contains(string(limits), escape) {
		t.Skipf("docs/limits.md no longer carries %q, so the promise has nothing to bound", escape)
	}

	for _, readme := range []string{"README.md", "README.fr.md"} {
		body, err := os.ReadFile(filepath.Join(root, readme))
		if err != nil {
			t.Fatalf("read %s: %v", readme, err)
		}
		promise := between(string(body), "<!-- promise:start -->", "<!-- promise:end -->")
		if promise == "" {
			t.Errorf("%s has no promise block; the generated markers moved and this check went blind",
				readme)
			continue
		}
		if !strings.Contains(promise, "docs/limits.md") {
			t.Errorf("%s promises locality without pointing at docs/limits.md, which measures four "+
				"paths out of it. An unqualified promise is the half-truth this repository keeps "+
				"catching in its own generated prose.\n--- block ---\n%s", readme, promise)
		}
	}
}
